  IF v ~ '_team$'            THEN RETURN true; END IF;
  IF v ~ '_mod$'             THEN RETURN true; END IF;
  IF v ~ '_moderator$'       THEN RETURN true; END IF;
  IF v ~ '_help$'            THEN RETURN true; END IF;

  RETURN false;
END;
